export default function LiquidLoader({ size = 220, progress }: LiquidLoaderProps) {
  const uid = useId().replace(/:/g, '');
  const isAuto = progress === undefined;

  // The SVG viewBox for the logo is "0 0 401 330"
  const vbW = 401;
  const vbH = 330;

  // Wave amplitude and frequency
  const waveH = 18; // px in viewBox units
  const waveW = vbW * 2; // wide enough to scroll

  // Build a wave path: starts at bottom-left, waves along top, closes at bottom-right
  // The wave is a sine-like shape using cubic bezier segments
  const buildWavePath = (phaseOffset: number) => {
    const seg = vbW / 4; // 4 wave cycles across the width
    let d = `M ${phaseOffset} ${waveH}`;
    for (let i = 0; i < 8; i++) {
      const x0 = phaseOffset + i * seg;
      const x1 = x0 + seg / 2;
      const x2 = x0 + seg;
      d += ` C ${x0 + seg / 4} 0, ${x1 - seg / 4} ${waveH * 2}, ${x2} ${waveH}`;
    }
    d += ` L ${phaseOffset + waveW} ${vbH} L ${phaseOffset} ${vbH} Z`;
    return d;
  };

  return (
    <div className="ll-wrapper" style={{ width: size, height: size * (vbH / vbW) }}>
      <svg
        viewBox={`0 0 ${vbW} ${vbH}`}
        xmlns="http://www.w3.org/2000/svg"
        className="ll-svg"
      >
        <defs>
          {/* === CLIP PATH: the logo silhouette === */}
          <clipPath id={`${uid}-clip`}>
            <path d={LOGO_PATH} />
          </clipPath>

          {/* === Gradient for the liquid === */}
          <linearGradient id={`${uid}-grad`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="white" />
            <stop offset="100%" stopColor="white" />
          </linearGradient>

          {/* === Glow filter === */}
          <filter id={`${uid}-glow`} x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="4" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* ─── Layer 1: Ghost outline of logo (dim fill so it reads as "empty container") ─── */}
        <path
          d={LOGO_PATH}
          fill="none"
          stroke="rgba(255,255,255,0.35)"
          strokeWidth="1.5"
          className="ll-outline"
        />

        {/* ─── Layer 2: The liquid fill, clipped strictly inside the logo ─── */}
        <g clipPath={`url(#${uid}-clip)`} filter={`url(#${uid}-glow)`}>
          {/* Solid liquid body */}
          <rect
            x="0"
            y="0"
            width={vbW}
            height={vbH}
            fill={`url(#${uid}-grad)`}
            className={isAuto ? 'll-liquid-body ll-liquid-auto' : 'll-liquid-body'}
            style={!isAuto ? { transform: `translateY(${(100 - progress) / 100 * vbH}px)` } : undefined}
          />

          {/* Wave 1 (front) */}
          <path
            d={buildWavePath(-vbW)}
            fill="rgba(255,255,255,0.6)"
            className={isAuto ? 'll-wave-front ll-wave-auto' : 'll-wave-front'}
            style={!isAuto ? { transform: `translateY(${(100 - progress) / 100 * vbH}px)` } : undefined}
          />

          {/* Wave 2 (back, slightly offset) */}
          <path
            d={buildWavePath(-vbW * 0.5)}
            fill="rgba(255,255,255,0.4)"
            className={isAuto ? 'll-wave-back ll-wave-auto' : 'll-wave-back'}
            style={!isAuto ? { transform: `translateY(${(100 - progress) / 100 * vbH}px)` } : undefined}
          />
        </g>
      </svg>
    </div>
  );
}
